<template>
	<transition name="announcement-fade">
		<view
			v-if="visible"
			class="announcement-mask"
			@touchmove.stop.prevent
		>
			<view class="announcement-panel">
				<image class="announcement-background" :src="imageUrl" mode="aspectFill" />
				<view class="announcement-background-fade" />

				<button
					class="announcement-close"
					hover-class="announcement-close-hover"
					aria-label="关闭公告"
					@click="close"
				>
					<text>×</text>
				</button>

				<scroll-view
					class="announcement-scroll"
					scroll-y
					:show-scrollbar="false"
				>
					<view class="announcement-body">
					<view class="announcement-label">
						<!-- <text class="announcement-label-dot" /> -->
						<text>{{ title }}</text>
					</view>
					<!-- <text class="announcement-title">{{ title }}</text> -->

					<view class="announcement-copy">
						<text
							v-for="(paragraph, index) in announcementParagraphs"
							:key="index"
							class="announcement-content"
						>{{ paragraph }}</text>
					</view>

					<button
						class="announcement-confirm"
						hover-class="announcement-confirm-hover"
						@click="confirm"
					>
						<text>{{ confirmText }}</text>
					</button>
					</view>
				</scroll-view>
			</view>
		</view>
	</transition>
</template>

<script>
export default {
	name: 'HomeAnnouncement',
	props: {
		visible: { type: Boolean, default: false },
		label: { type: String, default: '遇见公告' },
		title: { type: String, default: '欢迎来到遇见' },
		content: {
			type: String,
			default: '亲爱的同频旅人：\n\n欢迎来到遇见。这里收纳每一种真实的心情，也珍惜每一次认真靠近的相遇。'
		},
		imageUrl: { type: String, default: '/static/img/yujian-bg.png' },
		confirmText: { type: String, default: '我知道了' }
	},
	methods: {
		close() {
			this.$emit('close');
		},
		confirm() {
			this.$emit('confirm');
		}
	},
	computed: {
		announcementParagraphs() {
			return String(this.content || '')
				.split(/\r?\n\s*\r?\n/)
				.map((paragraph) => paragraph.trim())
				.filter(Boolean);
		}
	}
};
</script>

<style lang="scss" scoped>
.announcement-mask {
	position: fixed;
	inset: 0;
	z-index: 10020;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 56rpx 48rpx;
	background: rgba(25, 22, 36, 0.56);
	backdrop-filter: blur(10rpx);
	-webkit-backdrop-filter: blur(10rpx);
}

.announcement-panel {
	position: relative;
	width: 100%;
	max-width: 620rpx;
	max-height: calc(100vh - 112rpx);
	overflow: hidden;
	border: 1rpx solid rgba(255, 255, 255, 0.86);
	border-radius: 28rpx;
	background: #ffffff;
	box-shadow: 0 34rpx 90rpx rgba(35, 28, 54, 0.3);
}

.announcement-background {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 390rpx;
	background: #f5eefe;
	-webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 54%, transparent 100%);
	mask-image: linear-gradient(to bottom, #000 0%, #000 54%, transparent 100%);
}

.announcement-background-fade {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 410rpx;
	background: linear-gradient(
		to bottom,
		rgba(255, 255, 255, 0) 38%,
		rgba(255, 255, 255, 0.5) 68%,
		#ffffff 100%
	);
}

.announcement-close {
	position: absolute;
	top: 18rpx;
	right: 18rpx;
	z-index: 2;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 58rpx;
	height: 58rpx;
	border: 1rpx solid rgba(255, 255, 255, 0.76);
	border-radius: 50%;
	background: rgba(255, 255, 255, 0.88);
	box-shadow: 0 8rpx 20rpx rgba(53, 42, 72, 0.14);
	color: #5b5268;
	font-size: 38rpx;
	font-weight: 300;
	line-height: 1;
}

.announcement-close-hover {
	background: #ffffff;
	transform: scale(0.96);
}

.announcement-scroll {
	position: relative;
	z-index: 1;
	width: 100%;
	max-height: calc(100vh - 112rpx);
}

.announcement-body {
	position: relative;
	z-index: 1;
	padding: 294rpx 38rpx 36rpx;
}

.announcement-label {
	display: flex;
	align-items: center;
	gap: 10rpx;
	color: #d4688a;
	font-size: 32rpx;
	font-weight: 700;
}

.announcement-label-dot {
	width: 10rpx;
	height: 10rpx;
	border-radius: 50%;
	background: #ef7ead;
	box-shadow: 0 0 0 7rpx rgba(239, 126, 173, 0.12);
}

.announcement-title {
	display: block;
	margin-top: 18rpx;
	color: #292746;
	font-size: 36rpx;
	font-weight: 800;
	line-height: 1.3;
}

.announcement-copy {
	display: flex;
	flex-direction: column;
	margin-top: 20rpx;
}

.announcement-content {
	display: block;
	color: #4f4659;
	font-family: "PingFang SC", "Microsoft YaHei", sans-serif;
	font-size: 28rpx;
	font-weight: 500;
	line-height: 1.9;
	text-align: left;
	white-space: pre-line;
	word-break: break-word;
}

.announcement-content + .announcement-content {
	margin-top: 18rpx;
}

.announcement-confirm {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	height: 82rpx;
	margin-top: 26rpx;
	border-radius: 14rpx;
	background: #e96f9f;
	box-shadow: 0 14rpx 30rpx rgba(224, 103, 151, 0.24);
	color: #ffffff;
	font-size: 27rpx;
	font-weight: 700;
}

.announcement-confirm-hover {
	background: #d96391;
	transform: translateY(1rpx);
}

.announcement-fade-enter-active {
	transition: opacity 260ms ease-out;
}

.announcement-fade-leave-active {
	transition: opacity 200ms ease-in;
}

.announcement-fade-enter-active .announcement-panel {
	transition: transform 340ms cubic-bezier(0.2, 0.76, 0.28, 1.06), opacity 260ms ease-out;
}

.announcement-fade-leave-active .announcement-panel {
	transition: transform 200ms ease-in, opacity 180ms ease-in;
}

.announcement-fade-enter,
.announcement-fade-leave-to {
	opacity: 0;
}

.announcement-fade-enter .announcement-panel,
.announcement-fade-leave-to .announcement-panel {
	opacity: 0;
	transform: translateY(30rpx) scale(0.95);
}
</style>
